// html-embed version of kak-tn.tex (same circuit, L2R convention).
// Labels are MathML generated by Temml; layout is CSS grid so that the
// math keeps its font size on narrow screens instead of being scaled down.
// usage: node images/intro-kak-decomposition/kak-tn-embed.mjs > images/intro-kak-decomposition/kak-tn.embed.html
import temml from "temml";

// Temml emits <mo stretchy="true">∑</mo> for an inline \sum; next to \bigl(
// Chrome then places it ~0.26em below the math axis. Dropping the attribute
// restores axis alignment.
const m = (tex) =>
  temml.renderToString(tex).replace(/<mo stretchy="true">([∑∏∐⋃⋂⨁⨂])<\/mo>/g, "<mo>$1</mo>");

const html = `<div class="kak" role="img" aria-label="KAK分解の回路図: 大域位相 e^{iφ} を除いて、量子ビット1と2にそれぞれ1量子ビットゲート K'1, K'2 を作用させ、次に2量子ビットにまたがる exp(i Σ c_α σ1α σ2α)、最後に K1, K2 を作用させる">
<div class="pre">${m("U \\;=\\; \\mathrm{e}^{\\mathrm{i}\\phi}\\;\\cdot")}</div>
<div class="grid">
<div class="lab r1">${m("1")}</div><div class="lab r2">${m("2")}</div>
<div class="wire r1"></div><div class="wire r2"></div>
<div class="g r1 c3">${m("K'_1")}</div><div class="g r2 c3">${m("K'_2")}</div>
<div class="g big">${m("\\exp\\bigl(\\mathrm{i}\\sum_\\alpha c_\\alpha\\sigma_{1\\alpha}\\sigma_{2\\alpha}\\bigr)")}</div>
<div class="g r1 c7">${m("K_1")}</div><div class="g r2 c7">${m("K_2")}</div>
</div>
</div>
<style>
:root{--fg:#1f2328;--bg:#ffffff}
[data-theme="dark"]{--fg:#e6edf3;--bg:#0d1117}
.kak{background:var(--bg);color:var(--fg);display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:4px 12px;padding:12px 8px}
math{font-size:18px}
.grid{display:grid;grid-template-columns:auto minmax(10px,28px) auto minmax(10px,40px) auto minmax(10px,40px) auto minmax(10px,28px);grid-template-rows:56px 56px;align-items:center}
.r1{grid-row:1}.r2{grid-row:2}
.lab{grid-column:1;padding-right:6px}
.wire{grid-column:2/-1;height:0;border-top:2px solid var(--fg)}
.g{position:relative;z-index:1;background:var(--bg);border:2px solid var(--fg);padding:4px 8px;justify-self:center}
.c3{grid-column:3}.c7{grid-column:7}
.big{grid-column:5;grid-row:1/3;align-self:stretch;margin:4px 0;display:flex;align-items:center;padding:0 12px}
</style>`;
process.stdout.write(html);
